-- Interest whitelist used by submit_enquiry (active keys only; deprecated ones can't be submitted).
create or replace function public.catalog_interest_keys()
returns text[]
language sql
immutable
set search_path = ''
as $$
  select array['term', 'endowment', 'money_back', 'child', 'pension', 'health', 'ulip', 'other']::text[]
$$;
revoke all on function public.catalog_interest_keys() from public, anon, authenticated;

