-- Months per premium mode (catalog.premiumModes[].months); null for an unknown mode.
create or replace function public.catalog_premium_mode_months(p_mode text)
returns integer
language sql
immutable
set search_path = ''
as $$
  select case p_mode when 'yearly' then 12 when 'half_yearly' then 6 when 'quarterly' then 3 when 'monthly' then 1 else null end
$$;
revoke all on function public.catalog_premium_mode_months(text) from public, anon, authenticated;

