-- Feature flag defaults and server-authoritative prices. Manual flag overrides live in the
-- `flag_overrides` row, which this never touches (effective flags: public.effective_flags()).
insert into public.app_config (key, value) values
  ('flags', '{"siteBuilder":true,"enquiries":true,"customers":true,"policies":true,"dues":true,"insights":true,"reminders":true,"csvExport":true,"servicePlan":true,"payments":true,"customDomains":true}'::jsonb),
  ('pricing', '{"service":{"purchaseInr":499,"renewalInr":299,"taxInclusive":true,"trialDays":14,"graceDays":15,"renewWindowDays":60,"reminderDays":[30,7,1],"graceReminderDays":[1,7,14]},"domain":{"source":"registrar_live","serviceFeeInr":99,"feeAppliesTo":["purchase","renewal"],"connectInr":0,"requiresPaidPlan":true,"allowedTlds":[".in",".co.in",".com"],"quoteValidMinutes":15,"renewWindowDays":60,"reminderDays":[30,7,1]}}'::jsonb)
on conflict (key) do update set value = excluded.value;
